{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "A human absolute oral bioavailability measurement of 47-73% for the highest-transfer analogue places it clearly above the 20% threshold and supports high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Tamoxifen, a lipophilic basic tertiary-amine drug, is reported to have almost 100% oral bioavailability in patients, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Apixaban absolute oral bioavailability was 0.49 (90% CI 0.42-0.59) after a 10 mg oral dose in humans, a direct human F value above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Encainide, a methoxy-substituted basic amide antiarrhythmic, had absolute oral bioavailability of 32 ± 7% in normal subjects, directly supporting F ≥ 20% for a structurally related query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Midodrine absolute oral bioavailability was 93% in healthy volunteers, providing strong human evidence of high oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Pentopril, an ester-containing drug, showed absolute oral bioavailability >58% in humans, supporting high F for the ester-containing query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferred experimental evidence points to oral bioavailability above 20%; multiple direct human absolute F values range from ~30% to ~100%, with no affirmative evidence of F < 20%, so the query is predicted high.",
  "evidence_gaps": [
    "No direct diltiazem-specific absolute bioavailability record is included; prediction relies on transferred analogues.",
    "Some records are not explicitly absolute bioavailability, though multiple absolute human measurements anchor the conclusion.",
    "Encainide shows wide interindividual variability (7-82%), so the lower tail can fall below 20%, but mean values remain above threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

